package io.knowledgebrain.content;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class DecisionRulesTest {
 @Test void completedDecisionRequiresExplicitOutcomeAndRationaleWhileDraftMayRetainBoth(){for(String v:List.of("", " \r\n\t", "\u3000")){assertThrows(org.springframework.web.server.ResponseStatusException.class,()->DecisionRules.input(new DecisionStore.Input("Decision","",v,"Reason","Alternative","DECIDED")));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->DecisionRules.input(new DecisionStore.Input("Decision","","Choice",v,"Alternative","DECIDED")));}assertDoesNotThrow(()->DecisionRules.input(new DecisionStore.Input("Decision","","","","","DRAFT")));assertDoesNotThrow(()->DecisionRules.input(new DecisionStore.Input("Decision","","Choice","Reason","Alternative","DECIDED")));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->DecisionRules.input(new DecisionStore.Input("Decision","","Choice","Reason","","VERIFIED")));}
 @Test void independentUtf8BoundsPreserveAllFourMultilineFields(){var v=new DecisionStore.Input("😀".repeat(200),"a".repeat(8192),"\r\n\t"+"b".repeat(8189),"c".repeat(8192),"d".repeat(8192),"DECIDED");assertDoesNotThrow(()->DecisionRules.input(v));for(var invalid:List.of(new DecisionStore.Input(" ","","","","","DRAFT"),new DecisionStore.Input("a\nb","","","","","DRAFT"),new DecisionStore.Input("😀".repeat(201),"","","","","DRAFT"),new DecisionStore.Input("q","a".repeat(8193),"","","","DRAFT"),new DecisionStore.Input("q","","b".repeat(8193),"","","DRAFT"),new DecisionStore.Input("q","","","c".repeat(8193),"","DRAFT"),new DecisionStore.Input("q","","","","d".repeat(8193),"DRAFT"),new DecisionStore.Input("q","\ud800","","","","DRAFT"),new DecisionStore.Input("q","","\u007f","","","DRAFT")))assertThrows(org.springframework.web.server.ResponseStatusException.class,()->DecisionRules.input(invalid));}
 @Test void uuidAndTraceValidation(){assertThrows(org.springframework.web.server.ResponseStatusException.class,()->DecisionRules.id(UUID.randomUUID().toString()));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->DecisionRules.trace("0".repeat(32)));}
}
